import sys

def main():
    data = sys.stdin.read().split()
    if data[0] == 'C':
        s = data[1]
        trie = {}
        out = []
        cur = 0
        cnt = 0
        for ch in s:
            key = (cur, ch)
            if key in trie:
                cur = trie[key]
            else:
                cnt += 1
                trie[key] = cnt
                out.append('%d %s' % (cur, ch))
                cur = 0
        if cur != 0:
            out.append('%d -' % cur)
        print('\n'.join(out))
    else:
        k = int(data[1])
        phrases = ['']
        res = []
        for t in range(k):
            idx = int(data[2 + 2 * t])
            ch = data[3 + 2 * t]
            if ch == '-':
                res.append(phrases[idx])
            else:
                p = phrases[idx] + ch
                phrases.append(p)
                res.append(p)
        print(''.join(res))

main()

